const inputData = $state.context;

// Process the input data to generate the desired output format
const products = {};
inputData.REQUEST.ITEMSHIPMENT.itemShipment.edges.forEach((itemShipment) => {
  itemShipment.node.lines.edges.forEach((line) => {
    const productId = line.node.itemNumber;

    if (!products[productId]) {
      products[productId] = {
        id: productId,
        andon: {},
        inventory: { edges: [] },
        acknowledgedByUser: {}
      };
    }

    if (line.node.andonRequests.edges.length > 0) {
      const andonRequest = line.node.andonRequests.edges[0].node;
      products[productId].andon = {
        id: andonRequest.id,
        number: andonRequest.number
      };
    }

    products[productId].acknowledgedByUser = {
      id: line.node.andonRequests.edges[0].node.acknowledgedByUser.id
    };
  });
});

inputData.REQUEST.DATA.inventory.edges.forEach((inventoryNode) => {
  const productId = inventoryNode.node.productStrategyProcess.productStrategy.product.id;

  if (products[productId]) {
    products[productId].inventory.edges.push(inventoryNode.node);
  }
});

const output = {
  products: Object.values(products)
};

return output;

const inputData = $state.context;





const payloadArray = [];

inputData.FINAL.products.forEach((product) => {
  const { inventory, andon } = product;
  inventory.edges.forEach((edge) => {
    const payloadItem = {
      create: {

        prodid:edge.productStrategyProcess.productStrategy.product.id,
        complete: false,
        loaded: true,
        number: edge.number,
        andonRequestId: andon.id,
        inventoryId: edge.id,
        masterInventoryId: edge.masterInventoryId // Use the provided masterInventoryId from inventory data
      }
    };
    payloadArray.push(payloadItem);
  });
});

return (payloadArray);

